"""Task-scoped helper script: European economic performance data storytelling.

Discovers the European economic performance data files in this workspace
directory, analyzes the numeric indicators they contain, and writes a markdown
data storytelling report (Hook -> Context -> Evidence -> Insights -> Resolution
-> Call to Action) as a task-scoped artifact, consistent with the registered
data-storytelling skill.
"""

import csv
import json
import os
import statistics
from pathlib import Path

WORKSPACE = Path.cwd()
REPORT_PATH = WORKSPACE / "europe_economic_performance_report.md"
DATA_EXTS = {".csv", ".tsv", ".json", ".txt"}
NAME_FIELDS = {"country", "economy", "name", "region", "member state",
               "country_name", "nation", "state", "entity", "country/region"}


def find_data_files():
    """Locate data files in this workspace (skipping hidden/derived dirs)."""
    found = []
    for root, dirs, files in os.walk(WORKSPACE):
        dirs[:] = [d for d in dirs if not d.startswith(".") and d != "__pycache__"]
        for name in sorted(files):
            p = Path(root) / name
            if p.suffix.lower() in DATA_EXTS:
                found.append(p)
    return found


def rows_from_data(data):
    """Normalize JSON structures into a list of dict rows."""
    if isinstance(data, list):
        if data and all(isinstance(r, dict) for r in data):
            return data
        return [{"value": v} for v in data]
    if isinstance(data, dict):
        rows = []
        for k, v in data.items():
            row = {"name": k}
            if isinstance(v, dict):
                row.update(v)
            else:
                row["value"] = v
            rows.append(row)
        return rows
    return [{"value": data}]


def rows_from_text(text):
    """Parse CSV/TSV-ish text or key:value lines into rows."""
    lines = text.splitlines()
    if not lines:
        return []
    delimiter = None
    try:
        delimiter = csv.Sniffer().sniff("\n".join(lines[:100]), delimiters=",;\t|").delimiter
    except csv.Error:
        delimiter = None
    if delimiter:
        try:
            rows = list(csv.DictReader(lines, delimiter=delimiter))
            if rows and any(str(v).strip() for r in rows for v in r.values()):
                return rows
        except Exception:
            pass
    if all(":" in ln for ln in lines[:5]):
        rows = []
        for ln in lines:
            if ":" in ln:
                k, v = ln.split(":", 1)
                rows.append({k.strip(): v.strip()})
        if rows:
            return rows
    return [{"line": ln} for ln in lines]


def load_rows(path):
    raw = path.read_text(encoding="utf-8", errors="replace")
    if path.suffix.lower() == ".json":
        try:
            return rows_from_data(json.loads(raw))
        except json.JSONDecodeError:
            return rows_from_text(raw)
    return rows_from_text(raw)


def to_float(value):
    if value is None:
        return None
    s = str(value).replace("%", "").replace(",", "").replace("$", "").strip()
    if not s or s.lower() in ("na", "n/a", "-", "nan", "null", "none", "--"):
        return None
    try:
        return float(s)
    except ValueError:
        return None


def field_unit(rows, field):
    for r in rows:
        v = r.get(field)
        if v is not None and "%" in str(v):
            return "%"
    return ""


def numeric_fields(rows):
    if not rows:
        return []
    fields = []
    for f in rows[0].keys():
        vals = [to_float(r.get(f)) for r in rows]
        if sum(1 for v in vals if v is not None) >= 2:
            fields.append(f)
    return fields


def summarize(rows):
    summary = {}
    for f in numeric_fields(rows):
        vals = [to_float(r.get(f)) for r in rows]
        vals = [v for v in vals if v is not None]
        if not vals:
            continue
        summary[f] = {
            "min": min(vals),
            "max": max(vals),
            "mean": sum(vals) / len(vals),
            "median": statistics.median(vals),
            "n": len(vals),
            "unit": field_unit(rows, f),
        }
    return summary


def name_field(rows):
    if not rows:
        return None
    keys = [str(k).strip().lower() for k in rows[0].keys()]
    for i, k in enumerate(keys):
        if k in NAME_FIELDS:
            return list(rows[0].keys())[i]
    return None


def fmt(v, nd=2):
    if isinstance(v, float):
        return f"{v:,.{nd}f}"
    return str(v)


def build_report(files_rows):
    out = []
    out.append("# Europe's Economic Scorecard: A Story of Contrast")
    out.append("")
    out.append("> *A data storytelling report generated from the European economic "
               "performance data found in this workspace directory.*")
    out.append("")

    if not files_rows:
        out.append("## What the Data Says")
        out.append("")
        out.append("No European economic performance data files (CSV, TSV, JSON, TXT) "
                   "were found in this workspace directory, so this report cannot assert "
                   "any numbers. The next step is to add the source data and re-run the "
                   "analysis.")
        return "\n".join(out)

    # Gather every numeric signal for the narrative.
    signals = []  # (field, min, max, unit, spread, source)
    for rel, rows in files_rows:
        for field, s in summarize(rows).items():
            spread = s["max"] - s["min"]
            signals.append((field, s["min"], s["max"], s["unit"], spread, rel))

    # --- The Hook ---------------------------------------------------------
    if signals:
        signals_sorted = sorted(signals, key=lambda t: t[4], reverse=True)
        field, lo, hi, unit, spread, src = signals_sorted[0]
        out.append("## The Hook")
        out.append("")
        out.append(f"Europe's recovery is not one story — it is many. The most striking "
                   f"signal in the data is **{field}**, which ranges from **{fmt(lo)} to "
                   f"{fmt(hi)}{unit}** — a spread of **{fmt(spread)}{unit}** across the "
                   f"observed economies. That gap is the difference between the economies "
                   f"pulling the region forward and the ones still waiting for the upturn.")
    else:
        out.append("## The Hook")
        out.append("")
        out.append("The available data is largely non-numeric, so the headline must be "
                   "read with caution: the picture of European economic performance is "
                   "incomplete until richer indicators are added.")
    out.append("")

    # --- The Context ------------------------------------------------------
    total_rows = sum(len(rows) for _, rows in files_rows)
    out.append("## The Context")
    out.append("")
    out.append(f"- Data sources analyzed: **{len(files_rows)}** file(s)")
    out.append(f"- Total observations: **{total_rows}**")
    out.append("")
    for rel, rows in files_rows:
        out.append(f"- `{rel}` — {len(rows)} rows, {len(numeric_fields(rows))} numeric "
                   f"indicator(s)")
    out.append("")
    out.append("A single average hides the spread. This report therefore looks at the "
               "full distribution — minimum, maximum, mean, and median — for every "
               "indicator, and at which entities sit at each end.")
    out.append("")

    # --- The Evidence -----------------------------------------------------
    out.append("## The Evidence: What the Data Shows")
    out.append("")
    for rel, rows in files_rows:
        out.append(f"### `{rel}`")
        out.append("")
        summary = summarize(rows)
        if not summary:
            out.append("No numeric indicators with at least two values were detected in "
                       "this file.")
            out.append("")
            continue
        out.append("| Indicator | Min | Max | Mean | Median | Obs. |")
        out.append("|-----------|-----|-----|------|--------|------|")
        for f, s in summary.items():
            out.append(f"| {f} | {fmt(s['min'])} | {fmt(s['max'])} | "
                       f"{fmt(s['mean'])} | {fmt(s['median'])} | {s['n']} |")
        out.append("")
        nf = name_field(rows)
        if nf:
            for f, s in summary.items():
                vals = [(to_float(r.get(f)), r.get(nf)) for r in rows]
                vals = [(v, n) for v, n in vals
                        if v is not None and n is not None and str(n).strip()]
                if not vals:
                    continue
                best = max(vals, key=lambda t: t[0])
                worst = min(vals, key=lambda t: t[0])
                out.append(f"- **{f}**: best performer **{best[1]}** at {fmt(best[0])}{s['unit']}; "
                           f"laggard **{worst[1]}** at {fmt(worst[0])}{s['unit']}.")
        out.append("")

    # --- The Key Insights -------------------------------------------------
    out.append("## The Key Insights")
    out.append("")
    if signals:
        widest = max(signals, key=lambda t: t[4])
        wf, wlo, whi, wunit, wspread, wsrc = widest
        out.append(f"1. **Heterogeneity is the defining feature.** {wf} spans "
                   f"{fmt(wlo)}–{fmt(whi)}{wunit} in `{wsrc}` — a {fmt(wspread)}{wunit} "
                   f"gap. Policy that assumes one European economy assumes wrongly.")
        skew_lines = []
        for rel, rows in files_rows:
            for f, s in summarize(rows).items():
                if abs(s["mean"] - s["median"]) > 0.01 * max(1.0, abs(s["median"])):
                    skew_lines.append(f"**{f}** (mean {fmt(s['mean'])}{s['unit']} vs "
                                      f"median {fmt(s['median'])}{s['unit']}) in `{rel}`")
        if skew_lines:
            out.append(f"2. **The average flatters.** In {'; '.join(skew_lines[:3])}, the "
                       "mean sits apart from the median — a few strong performers are "
                       "masking the middle of the distribution.")
        else:
            out.append("2. **Central tendency is stable.** Mean and median track closely "
                       "across the indicators, so the headline averages are not being "
                       "distorted by outliers.")
        out.append("3. **Coverage varies by source.** Files with the most numeric "
                   "indicators support the strongest claims; the rest of the story must "
                   "be read as indicative, not conclusive.")
    else:
        out.append("No robust numeric patterns could be established from the available "
                   "files; the insights below are therefore directional.")
    out.append("")

    # --- The Resolution ---------------------------------------------------
    out.append("## The Resolution: What the Data Suggests")
    out.append("")
    if signals:
        widest_field = max(signals, key=lambda t: t[4])[0]
        out.append("1. **Target the laggards, not just the leaders.** The widest gaps are "
                   f"in **{widest_field}**. Closing the bottom of the distribution to the "
                   "median would lift the regional average far more than pushing the top "
                   "further.")
    out.append("2. **Watch the skew, set targets on the median.** Where mean and median "
               "diverge, headline growth is being carried by a minority of economies; "
               "base targets on the median so success is measured for the region, not "
               "just its strongest members.")
    out.append("3. **Standardize the indicators.** Several observations lacked numeric "
               "values or consistent naming; consistent reporting will make the next "
               "edition of this story measurably stronger.")
    out.append("")

    # --- Call to Action ---------------------------------------------------
    out.append("## Call to Action")
    out.append("")
    out.append("Open the next economic review with this scorecard: agree on the three "
               "indicators that matter most, assign owners to the laggard economies, and "
               "re-run this analysis each quarter to track whether the spread is closing.")
    out.append("")

    # --- Appendix ---------------------------------------------------------
    out.append("## Appendix: Source Data")
    out.append("")
    for rel, rows in files_rows:
        out.append(f"### `{rel}`")
        out.append("")
        if not rows:
            out.append("_No rows._")
            out.append("")
            continue
        fields = []
        for r in rows:
            for k in r.keys():
                if k not in fields:
                    fields.append(k)
        out.append("| " + " | ".join(fields) + " |")
        out.append("|" + "---|" * len(fields))
        for r in rows[:40]:
            out.append("| " + " | ".join(str(r.get(f, "")).replace("|", "\\|")
                                         for f in fields) + " |")
        if len(rows) > 40:
            out.append(f"_… {len(rows) - 40} more row(s) omitted._")
        out.append("")

    return "\n".join(out)


def main():
    files = find_data_files()
    files_rows = []
    for p in files:
        try:
            rows = load_rows(p)
        except Exception as exc:  # keep the report honest about unreadable files
            rows = [{"error": str(exc)}]
        files_rows.append((p.relative_to(WORKSPACE).as_posix(), rows))
    report = build_report(files_rows)
    REPORT_PATH.write_text(report, encoding="utf-8")
    print(report)
    print("\n\n[Report written to] " + str(REPORT_PATH))


if __name__ == "__main__":
    main()

"""Task-scoped inspection helper: list files in the workspace so the
European economic performance data can be located for the storytelling report."""
import os
import sys

base = os.getcwd()
print("WORKSPACE_ROOT:", base)

# Optional depth limit from argv, e.g. --depth 3
depth = 3
argv = sys.argv[1:]
if "--depth" in argv:
    i = argv.index("--depth")
    if i + 1 < len(argv):
        try:
            depth = int(argv[i + 1])
        except ValueError:
            pass

def walk(root, current_depth):
    if current_depth > depth:
        return
    entries = sorted(os.scandir(root), key=lambda e: (e.is_file(), e.name.lower()))
    for entry in entries:
        rel = os.path.relpath(entry.path, base)
        if entry.is_dir():
            if entry.name.startswith("."):
                continue
            print(f"[DIR ] {rel}")
            walk(entry.path, current_depth + 1)
        else:
            try:
                size = entry.stat().st_size
            except OSError:
                size = -1
            print(f"[FILE] {rel} ({size} bytes)")

walk(base, 1)

