        out.append("No robust numeric patterns could be established from the available "
                   "files; the insights below are therefore directional.")
    out.append("")

    # --- The Resolution ---------------------------------------------------
    out.append("## The Resolution: What the Data Suggests")
    out.append("")
    if signals:
        widest_field = max(signals, key=lambda t: t[4])[0]
        out.append("1. **Target the laggards, not just the leaders.** The widest gaps are "
                   f"in **{widest_field}**. Closing the bottom of the distribution to the "
                   "median would lift the regional average far more than pushing the top "
                   "further.")
    out.append("2. **Watch the skew, set targets on the median.** Where mean and median "
               "diverge, headline growth is being carried by a minority of economies; "
               "base targets on the median so success is measured for the region, not "
               "just its strongest members.")
    out.append("3. **Standardize the indicators.** Several observations lacked numeric "
               "values or consistent naming; consistent reporting will make the next "
               "edition of this story measurably stronger.")
    out.append("")

    # --- Call to Action ---------------------------------------------------
    out.append("## Call to Action")
    out.append("")
    out.append("Open the next economic review with this scorecard: agree on the three "
               "indicators that matter most, assign owners to the laggard economies, and "
               "re-run this analysis each quarter to track whether the spread is closing.")
    out.append("")

    # --- Appendix ---------------------------------------------------------
    out.append("## Appendix: Source Data")
    out.append("")
    for rel, rows in files_rows:
        out.append(f"### `{rel}`")
        out.append("")
        if not rows:
            out.append("_No rows._")
            out.append("")
            continue
        fields = []
        for r in rows:
            for k in r.keys():
                if k not in fields:
                    fields.append(k)
        out.append("| " + " | ".join(fields) + " |")
        out.append("|" + "---|" * len(fields))
        for r in rows[:40]:
            out.append("| " + " | ".join(str(r.get(f, "")).replace("|", "\\|")
                                         for f in fields) + " |")
        if len(rows) > 40:
            out.append(f"_… {len(rows) - 40} more row(s) omitted._")
        out.append("")

    return "\n".join(out)


def main():
    files = find_data_files()
    files_rows = []
    for p in files:
        try:
            rows = load_rows(p)
        except Exception as exc:  # keep the report honest about unreadable files
            rows = [{"error": str(exc)}]
        files_rows.append((p.relative_to(WORKSPACE).as_posix(), rows))
    report = build_report(files_rows)
    REPORT_PATH.write_text(report, encoding="utf-8")
    print(report)
    print("\n\n[Report written to] " + str(REPORT_PATH))


if __name__ == "__main__":
    main()
